function morningOverrideOptions(value){return `<option value="inherit" ${value===undefined?'selected':''}>طبق پیش‌فرض بخش</option><option value="1" ${value===true?'selected':''}>مورنینگ دارد</option><option value="0" ${value===false?'selected':''}>مورنینگ ندارد</option>`;}
function renderWeeklyMorning(){const box=$('#weeklyMorningGrid');if(!box)return;let h='<table><thead><tr><th>بخش</th>'+week.map(w=>`<th>${w}</th>`).join('')+'</tr></thead><tbody>';for(const s of state.shifts){h+=`<tr><td>${escHtml(s.name)}</td>`;for(let wd=0;wd<7;wd++){const val=state.weeklyMorning?.[wd]?.[s.id];h+=`<td><select data-week-morning="${wd}:${s.id}">${morningOverrideOptions(val)}</select></td>`;}h+='</tr>'; }h+='</tbody></table>';box.innerHTML=h;box.querySelectorAll('[data-week-morning]').forEach(sel=>sel.onchange=()=>{const [wd,id]=sel.dataset.weekMorning.split(':');state.weeklyMorning[wd]??={};if(sel.value==='inherit')delete state.weeklyMorning[wd][id];else state.weeklyMorning[wd][id]=sel.value==='1';state.assignments=[];save();renderCalendar();});}

