$('#importFile').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{importedRows=await XLSXLite.readFirstSheet(f);if(!importedRows.length)throw new Error('فایل خالی است');renderMapping(importedRows);$('#mappingBox').classList.remove('hidden');toast('فایل خوانده شد؛ معنی ستون‌ها را بررسی کن');}catch(err){alert('فایل خوانده نشد: '+err.message);}};
const mapIds=['mapName','mapTarget','mapHoliday','mapAllow48','mapUnavailable','mapPreferred','mapTogether','mapAvoid','mapStartDay','mapEndDay','mapPrevMorning','mapAllowedShifts','mapMaxConsecutive','mapPrevShifts','mapPrevHolidays','mapWUnavailable','mapWPreferred','mapWTogether','mapWAvoid','mapWMorning'];
const mapHints={mapName:['نام','اسم','name'],mapTarget:['تعداد کشیک'],mapHoliday:['تعداد کشیک تعطیل'],mapAllow48:['اجازه ۴۸','پشت‌سرهم'],mapUnavailable:['روزهای ممنوع','محدودیت'],mapPreferred:['روزهای ترجیحی'],mapTogether:['جفت با'],mapAvoid:['نباشد با','جفت نشدن'],mapStartDay:['از روز','شروع'],mapEndDay:['تا روز','پایان'],mapPrevMorning:['مورنینگ ماه‌های قبل'],mapAllowedShifts:['بخش‌های مجاز','شیفت‌های مجاز'],mapMaxConsecutive:['حداکثر روز'],mapPrevShifts:['کشیک ماه‌های قبل'],mapPrevHolidays:['کشیک تعطیل ماه‌های قبل'],mapWUnavailable:['اولویت روز ممنوع'],mapWPreferred:['اولویت روز ترجیحی'],mapWTogether:['اولویت جفت'],mapWAvoid:['اولویت جفت نشدن'],mapWMorning:['اولویت مورنینگ']};
function renderMapping(rows){const headers=(rows[0]||[]).map((x,i)=>String(x||`ستون ${i+1}`).trim()||`ستون ${i+1}`);for(const id of mapIds){const sel=$('#'+id);sel.innerHTML=(id==='mapName'?'':'<option value="">انتخاب نشده</option>')+headers.map((h,i)=>`<option value="${i}">${escHtml(h)}</option>`).join('');const found=headers.findIndex(h=>(mapHints[id]||[]).some(k=>h.toLowerCase().includes(k.toLowerCase())));if(found>=0)sel.value=String(found);}const preview=rows.slice(0,7),max=Math.max(...preview.map(r=>r.length));$('#preview').innerHTML='<table><tbody>'+preview.map((r,ri)=>'<tr>'+Array.from({length:max},(_,i)=>`<${ri?'td':'th'}>${escHtml(r[i]??'')}</${ri?'td':'th'}>`).join('')+'</tr>').join('')+'</tbody></table>';applyModeUI();}
$('#doImport').onclick=()=>{if(!importedRows)return;const get=id=>$('#'+id).value===''?null:Number($('#'+id).value),m=Object.fromEntries(mapIds.map(id=>[id,get(id)]));if(m.mapName==null)return toast('ستون نام را انتخاب کن');const val=(r,i)=>i==null?'':r[i],num=(r,i,d=0)=>{if(i==null)return d;const n=Number(latinDigits(val(r,i)));return Number.isFinite(n)&&String(val(r,i)).trim()!==''?n:d;};if(state.seededDemo){state.people=[];state.seededDemo=false;}const pending=[];for(const r of importedRows.slice(1)){const name=String(val(r,m.mapName)||'').trim();if(!name)continue;const p=newPerson({name});if(state.mode==='advanced'){p.targetShifts=num(r,m.mapTarget,0);p.targetHolidays=num(r,m.mapHoliday,0);p.allow48=m.mapAllow48==null?false:truthy(val(r,m.mapAllow48));p.preferredDays=parseDays(val(r,m.mapPreferred));p.startDay=num(r,m.mapStartDay,1)||1;p.endDay=num(r,m.mapEndDay,daysInMonth())||daysInMonth();p.previousMorning=num(r,m.mapPrevMorning,0);p.maxConsecutiveDays=num(r,m.mapMaxConsecutive,0);p.previousShifts=num(r,m.mapPrevShifts,0);p.previousHolidays=num(r,m.mapPrevHolidays,0);p.ruleWeights={unavailable:m.mapWUnavailable==null||String(val(r,m.mapWUnavailable)).trim()===''?null:clampWeight(num(r,m.mapWUnavailable)),preferred:m.mapWPreferred==null||String(val(r,m.mapWPreferred)).trim()===''?null:clampWeight(num(r,m.mapWPreferred)),together:m.mapWTogether==null||String(val(r,m.mapWTogether)).trim()===''?null:clampWeight(num(r,m.mapWTogether)),avoid:m.mapWAvoid==null||String(val(r,m.mapWAvoid)).trim()===''?null:clampWeight(num(r,m.mapWAvoid)),morning:m.mapWMorning==null||String(val(r,m.mapWMorning)).trim()===''?null:clampWeight(num(r,m.mapWMorning))};}p.unavailableDays=parseDays(val(r,m.mapUnavailable));pending.push({p,together:splitNames(val(r,m.mapTogether)),avoid:splitNames(val(r,m.mapAvoid)),allowed:splitNames(val(r,m.mapAllowedShifts))});}
  for(const x of pending){let p=state.people.find(q=>q.name.trim()===x.p.name);if(!p){p=x.p;state.people.push(p);}else Object.assign(p,x.p);}for(const x of pending){const p=state.people.find(q=>q.name.trim()===x.p.name);p.togetherIds=x.together.map(n=>state.people.find(q=>q.name.trim()===n)?.id).filter(Boolean);p.avoidIds=x.avoid.map(n=>state.people.find(q=>q.name.trim()===n)?.id).filter(Boolean);p.allowedShiftIds=x.allowed.map(n=>state.shifts.find(s=>s.name.trim()===n)?.id).filter(Boolean);}normalizePeopleLinks();state.assignments=[];save();renderPeople();go('people');toast(`${pending.length} نفر وارد شد`);
};

